const c=$json.contract; const errors=[];
if(!c||typeof c!=='object') errors.push('contract_missing');
if(!String(c?.objective||'').trim()) errors.push('objective_missing');
if(!Array.isArray(c?.allowedFiles)||c.allowedFiles.length===0) errors.push('allowed_files_missing');
if(!Array.isArray(c?.acceptance)||c.acceptance.length===0) errors.push('acceptance_missing');
if(c?.allowExternalWrites===true) errors.push('external_writes_forbidden');
return [{json:{...$json, contractValid:errors.length===0, contractErrors:errors}}];

const e=$json.evidence; const errors=[];
if(!e||typeof e!=='object') errors.push('evidence_missing');
if(!Array.isArray(e?.changedFiles)) errors.push('changed_files_missing');
if(e?.diffCheck?.status!==0) errors.push('diff_check_failed');
if(!Array.isArray(e?.tests)||e.tests.length===0) errors.push('tests_missing');
if(Array.isArray(e?.tests)&&e.tests.some(t=>Number(t.status)!==0)) errors.push('test_failed');
if($json.contract?.runtime?.required===true && (!e?.runtime || Number(e.runtime.status)!==Number($json.contract.runtime.expectedStatus||0))) errors.push('runtime_readback_failed');
return [{json:{...$json, evidenceValid:errors.length===0, evidenceErrors:errors}}];
